func enabledCount(flows []model.Flow) int {
	n := 0
	for _, f := range flows {
		if f.Enabled {
			n++
		}
	}
	return n
}
func readyCount(connections []model.Connection) int {
	n := 0
	for _, c := range connections {
		if c.Status == "ready" {
			n++
		}
	}
	return n
}

